    /// <summary>
    /// 建立 1D 可分離對稱高斯模糊算子（半徑限制 1~50）。
    /// </summary>
    public static ConvolutionKernel CreateGaussian(int radius = 2, float? sigma = null)
    {
        radius = global::System.Math.Clamp(radius, 1, 50);
        int size = radius * 2 + 1;
        float[] weights = new float[size];
        float s = sigma ?? global::System.Math.Max((float)radius / 2.0f, 0.5f);
        float twoSigmaSq = 2.0f * s * s;
        float sum = 0f;

        for (int i = -radius; i <= radius; i++)
        {
            float val = MathF.Exp(-(i * i) / twoSigmaSq);
            weights[i + radius] = val;
            sum += val;
        }

        for (int i = 0; i < size; i++) weights[i] /= sum;
        return CreateSeparable(weights, weights, name: $"GaussianBlur(r={radius})");
    }

