        Convolve<IdentityConvolutionPostProcessor>(source, kernel, default, options);

    /// <summary>
    /// 對 Bitmap 套用卷積算子與零開銷泛型結構後處理，並回傳新的 WriteableBitmap。
    /// </summary>
    public static WriteableBitmap Convolve<TPost>(
        Bitmap source,
        ConvolutionKernel kernel,
        TPost postProcessor,
        ConvolutionOptions? options = null)
        where TPost : struct, IConvolutionPostProcessor
    {
        ArgumentNullException.ThrowIfNull(source);
        ArgumentNullException.ThrowIfNull(kernel);

        var srcWb = source.ConvertToWriteableBitmap();
        var dstWb = new WriteableBitmap(
            srcWb.PixelSize,
            srcWb.Dpi,
            Platform.PixelFormat.Bgra8888,
            Platform.AlphaFormat.Premul);

        var opts = options ?? ConvolutionOptions.Default;
        Execute(srcWb, dstWb, kernel, postProcessor, opts);
        return dstWb;
    }

    private static void Execute<TPost>(
        WriteableBitmap src,
        WriteableBitmap dst,
        ConvolutionKernel kernel,
        TPost postProcessor,
        ConvolutionOptions options)
        where TPost : struct, IConvolutionPostProcessor
    {
        switch (kernel.Kind)
        {
            case ConvolutionKernelKind.Matrix2D:
                ExecuteMatrix2D(src, dst, kernel, postProcessor, options);
                break;
            case ConvolutionKernelKind.Separable1D:
                ExecuteSeparable1D(src, dst, kernel, postProcessor, options);
                break;
            case ConvolutionKernelKind.GradientDual2D:
                ExecuteGradientDual2D(src, dst, kernel, postProcessor, options);
                break;
            default:
                throw new NotSupportedException($"不支援的卷積算子類型: {kernel.Kind}");
        }
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static bool ShouldPreserveAlpha(ConvolutionKernel kernel, ConvolutionAlphaMode alphaMode) =>
        alphaMode switch
