    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static int ResolveBorderCoord(int coord, int max, ConvolutionBorderMode borderMode)
    {
        if ((uint)coord < (uint)max) return coord;

        switch (borderMode)
        {
            case ConvolutionBorderMode.Clamp:
                return coord < 0 ? 0 : max - 1;
            case ConvolutionBorderMode.Zero:
                return -1;
            case ConvolutionBorderMode.Reflect:
