        var vBytes = Vector128.CreateScalarUnsafe(*(uint*)ptr).AsByte();
        var vU16 = Vector128.WidenLower(vBytes);
        var vU32 = Vector128.WidenLower(vU16);
        return Vector128.ConvertToSingle(vU32.AsInt32());
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static void StoreFloat256As8Bytes(Vector256<float> acc, byte* dst)
    {
        var vClamped = Vector256.Clamp(acc + Vector256.Create(0.5f), Vector256<float>.Zero, Vector256.Create(255.0f));
        var vI32 = Vector256.ConvertToInt32(vClamped);
        var vPack16 = Vector128.Narrow(vI32.GetLower(), vI32.GetUpper());
        var vPack8 = Vector128.Narrow(vPack16.AsUInt16(), vPack16.AsUInt16());
        *(ulong*)dst = vPack8.AsUInt64().GetElement(0);
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static void StoreFloat128As4Bytes(Vector128<float> acc, byte* dst)
    {
        var vClamped = Vector128.Clamp(acc + Vector128.Create(0.5f), Vector128<float>.Zero, Vector128.Create(255.0f));
        var vI32 = Vector128.ConvertToInt32(vClamped);
        var vPack16 = Vector128.Narrow(vI32, vI32);
        var vPack8 = Vector128.Narrow(vPack16.AsUInt16(), vPack16.AsUInt16());
        *(uint*)dst = vPack8.AsUInt32().GetElement(0);
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static byte* RentScratch(long totalBytes, out byte[]? pooled, out byte* native)
    {
        if (totalBytes <= 64L * 1024 * 1024)
        {
            pooled = s_frameScratchPool.Rent((int)totalBytes);
            native = null;
            return null;
        }
        pooled = null;
        native = (byte*)System.Runtime.InteropServices.NativeMemory.Alloc((nuint)totalBytes);
        return native;
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static void ReturnScratch(byte[]? pooled, byte* native)
    {
        if (pooled != null) s_frameScratchPool.Return(pooled);
        if (native != null) System.Runtime.InteropServices.NativeMemory.Free(native);
    }

    // ==========================================
    // 管線 A：通用 2D 稀疏權重卷積 (Matrix2D)
    // ==========================================

    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    private static void ExecuteMatrix2D<TPost>(
        WriteableBitmap src,
        WriteableBitmap dst,
        ConvolutionKernel kernel,
        TPost postProcessor,
        ConvolutionOptions options)
        where TPost : struct, IConvolutionPostProcessor
    {
        bool inPlace = ReferenceEquals(src, dst);
        using var srcFb = src.Lock();
        using var dstFb = inPlace ? null : dst.Lock();

        int width = srcFb.Size.Width;
        int height = srcFb.Size.Height;
        int srcRowBytes = srcFb.RowBytes;
        int dstRowBytes = dstFb?.RowBytes ?? srcRowBytes;

        byte* srcOriginal = (byte*)srcFb.Address;
        byte* dstScan0 = dstFb != null ? (byte*)dstFb.Address : srcOriginal;

        long copyBytes = inPlace ? (long)srcRowBytes * height : 0;
        byte[]? pooled = null;
        byte* native = null;
        if (inPlace)
        {
            RentScratch(copyBytes, out pooled, out native);
        }

        try
        {
            fixed (byte* pooledPtr = pooled)
            {
                byte* srcScan0 = inPlace ? (pooled != null ? pooledPtr : native) : srcOriginal;
                if (inPlace)
                {
                    Buffer.MemoryCopy(srcOriginal, srcScan0, copyBytes, copyBytes);
                }

                bool isParallel = options.ProcessingMode is PixelProcessingMode.Parallel or PixelProcessingMode.ParallelVectorized;
                bool isVectorized = options.ProcessingMode is PixelProcessingMode.SequentialVectorized or PixelProcessingMode.ParallelVectorized;
                bool preserveAlpha = ShouldPreserveAlpha(kernel, options.AlphaMode);
                var taps = kernel.Sparse2DTaps;
                int rx = kernel.RadiusX;
                int ry = kernel.RadiusY;
                float bias = kernel.Bias;
                var borderMode = options.BorderMode;

                if (isParallel)
                {
                    Parallel.For(0, height, y =>
                        Matrix2DRow(srcScan0, dstScan0 + y * dstRowBytes, y, width, height, srcRowBytes, rx, ry, taps, bias, preserveAlpha, borderMode, isVectorized, postProcessor));
                }
                else
                {
                    for (int y = 0; y < height; y++)
                    {
                        Matrix2DRow(srcScan0, dstScan0 + y * dstRowBytes, y, width, height, srcRowBytes, rx, ry, taps, bias, preserveAlpha, borderMode, isVectorized, postProcessor);
                    }
                }
            }
        }
        finally
        {
            ReturnScratch(pooled, native);
        }
    }

    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    private static void Matrix2DRow<TPost>(
        byte* srcScan0,
        byte* dstRow,
        int y,
        int width,
        int height,
        int srcRowBytes,
        int rx,
        int ry,
        ConvolutionKernel.SparseTap[] taps,
        float bias,
        bool preserveAlpha,
        ConvolutionBorderMode borderMode,
        bool vectorized,
        TPost postProcessor)
        where TPost : struct, IConvolutionPostProcessor
    {
        byte* srcCurrRow = srcScan0 + y * srcRowBytes;
        bool hasPost = typeof(TPost) != typeof(IdentityConvolutionPostProcessor);
        bool rowInterior = y >= ry && y < height - ry;

        if (!rowInterior || !vectorized || hasPost)
        {
            int xStart = 0;
            int xEnd = width;
            if (!hasPost && vectorized && rowInterior)
            {
                // 處理前 rx 個左邊界
                Matrix2DBorderRange(srcScan0, srcCurrRow, dstRow, y, 0, global::System.Math.Min(rx, width), width, height, srcRowBytes, taps, bias, preserveAlpha, borderMode, postProcessor);
                xStart = global::System.Math.Min(rx, width);
                xEnd = global::System.Math.Max(xStart, width - rx);
            }
            else
            {
                Matrix2DBorderRange(srcScan0, srcCurrRow, dstRow, y, 0, width, width, height, srcRowBytes, taps, bias, preserveAlpha, borderMode, postProcessor);
                return;
            }

            // 中央安全區走純 SIMD
            Matrix2DInteriorSimd(srcScan0, srcCurrRow, dstRow, y, xStart, xEnd, srcRowBytes, taps, bias, preserveAlpha);
            // 右邊界
            Matrix2DBorderRange(srcScan0, srcCurrRow, dstRow, y, xEnd, width, width, height, srcRowBytes, taps, bias, preserveAlpha, borderMode, postProcessor);
            return;
        }

        int interiorStart = global::System.Math.Min(rx, width);
        int interiorEnd = global::System.Math.Max(interiorStart, width - rx);

        Matrix2DBorderRange(srcScan0, srcCurrRow, dstRow, y, 0, interiorStart, width, height, srcRowBytes, taps, bias, preserveAlpha, borderMode, postProcessor);
        Matrix2DInteriorSimd(srcScan0, srcCurrRow, dstRow, y, interiorStart, interiorEnd, srcRowBytes, taps, bias, preserveAlpha);
        Matrix2DBorderRange(srcScan0, srcCurrRow, dstRow, y, interiorEnd, width, width, height, srcRowBytes, taps, bias, preserveAlpha, borderMode, postProcessor);
    }

    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    private static void Matrix2DInteriorSimd(
        byte* srcScan0,
        byte* srcCurrRow,
        byte* dstRow,
        int y,
        int xStart,
        int xEnd,
        int srcRowBytes,
        ConvolutionKernel.SparseTap[] taps,
        float bias,
        bool preserveAlpha)
    {
        int x = xStart;

        if (Vector256.IsHardwareAccelerated && xEnd - x >= 2)
        {
            var vBias = Vector256.Create(bias);
            for (; x + 2 <= xEnd; x += 2)
            {
                var acc = vBias;
                for (int t = 0; t < taps.Length; t++)
                {
                    var tap = taps[t];
                    byte* p = srcScan0 + (y + tap.Dy) * srcRowBytes + (x + tap.Dx) * 4;
                    acc += Load8BytesAsFloat256(p) * Vector256.Create(tap.Weight);
                }

                byte* outPtr = dstRow + x * 4;
                if (preserveAlpha)
                {
                    ulong origAlpha = *(ulong*)(srcCurrRow + x * 4) & 0xFF000000FF000000UL;
                    StoreFloat256As8Bytes(acc, outPtr);
                    *(ulong*)outPtr = (*(ulong*)outPtr & 0x00FFFFFF00FFFFFFUL) | origAlpha;
                }
                else
                {
                    StoreFloat256As8Bytes(acc, outPtr);
                }
            }
        }

        if (Vector128.IsHardwareAccelerated)
        {
            var vBias = Vector128.Create(bias);
            for (; x < xEnd; x++)
            {
                var acc = vBias;
                for (int t = 0; t < taps.Length; t++)
                {
                    var tap = taps[t];
                    byte* p = srcScan0 + (y + tap.Dy) * srcRowBytes + (x + tap.Dx) * 4;
                    acc += Load4BytesAsFloat128(p) * Vector128.Create(tap.Weight);
                }

                byte* outPtr = dstRow + x * 4;
                if (preserveAlpha)
                {
                    uint origAlpha = *(uint*)(srcCurrRow + x * 4) & 0xFF000000u;
                    StoreFloat128As4Bytes(acc, outPtr);
                    *(uint*)outPtr = (*(uint*)outPtr & 0x00FFFFFFu) | origAlpha;
                }
                else
                {
                    StoreFloat128As4Bytes(acc, outPtr);
                }
            }
            return;
        }

        for (; x < xEnd; x++)
        {
            float b = bias, g = bias, r = bias, a = bias;
            for (int t = 0; t < taps.Length; t++)
            {
                var tap = taps[t];
                byte* p = srcScan0 + (y + tap.Dy) * srcRowBytes + (x + tap.Dx) * 4;
                float w = tap.Weight;
                b += p[0] * w; g += p[1] * w; r += p[2] * w;
                if (!preserveAlpha) a += p[3] * w;
            }
            byte* outP = dstRow + x * 4;
            outP[0] = (byte)global::System.Math.Clamp((int)(b + 0.5f), 0, 255);
            outP[1] = (byte)global::System.Math.Clamp((int)(g + 0.5f), 0, 255);
            outP[2] = (byte)global::System.Math.Clamp((int)(r + 0.5f), 0, 255);
            outP[3] = preserveAlpha ? srcCurrRow[x * 4 + 3] : (byte)global::System.Math.Clamp((int)(a + 0.5f), 0, 255);
        }
    }

    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    private static void Matrix2DBorderRange<TPost>(
        byte* srcScan0,
        byte* srcCurrRow,
        byte* dstRow,
        int y,
        int xStart,
        int xEnd,
        int width,
        int height,
        int srcRowBytes,
        ConvolutionKernel.SparseTap[] taps,
        float bias,
        bool preserveAlpha,
        ConvolutionBorderMode borderMode,
        TPost postProcessor)
        where TPost : struct, IConvolutionPostProcessor
    {
        bool hasPost = typeof(TPost) != typeof(IdentityConvolutionPostProcessor);

        for (int x = xStart; x < xEnd; x++)
        {
            float b = bias, g = bias, r = bias, a = preserveAlpha ? srcCurrRow[x * 4 + 3] : bias;
            for (int t = 0; t < taps.Length; t++)
            {
                var tap = taps[t];
                int sy = ResolveBorderCoord(y + tap.Dy, height, borderMode);
                if (sy < 0) continue;
                int sx = ResolveBorderCoord(x + tap.Dx, width, borderMode);
                if (sx < 0) continue;

                byte* p = srcScan0 + sy * srcRowBytes + sx * 4;
                float w = tap.Weight;
                b += p[0] * w;
                g += p[1] * w;
                r += p[2] * w;
                if (!preserveAlpha) a += p[3] * w;
            }

            if (hasPost)
            {
                postProcessor.PostProcess(x, y, ref b, ref g, ref r, ref a);
            }

            byte* outP = dstRow + x * 4;
            outP[0] = (byte)global::System.Math.Clamp((int)global::System.Math.Round(b), 0, 255);
            outP[1] = (byte)global::System.Math.Clamp((int)global::System.Math.Round(g), 0, 255);
            outP[2] = (byte)global::System.Math.Clamp((int)global::System.Math.Round(r), 0, 255);
            outP[3] = (byte)global::System.Math.Clamp((int)global::System.Math.Round(a), 0, 255);
        }
    }

    // ==========================================
    // 管線 B：1D 可分離卷積 (Separable1D)
    // ==========================================

    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    private static void ExecuteSeparable1D<TPost>(
        WriteableBitmap src,
        WriteableBitmap dst,
        ConvolutionKernel kernel,
        TPost postProcessor,
        ConvolutionOptions options)
        where TPost : struct, IConvolutionPostProcessor
    {
        bool inPlace = ReferenceEquals(src, dst);
        using var srcFb = src.Lock();
        using var dstFb = inPlace ? null : dst.Lock();

        int width = srcFb.Size.Width;
        int height = srcFb.Size.Height;
        int srcRowBytes = srcFb.RowBytes;
        int dstRowBytes = dstFb?.RowBytes ?? srcRowBytes;

        byte* srcScan0 = (byte*)srcFb.Address;
        byte* dstScan0 = dstFb != null ? (byte*)dstFb.Address : srcScan0;

        int hSize = kernel.Width;
        int vSize = kernel.Height;
        int rx = kernel.RadiusX;
        int ry = kernel.RadiusY;

        float* hKernel = stackalloc float[hSize];
        float* vKernel = stackalloc float[vSize];
        var hSpan = kernel.HorizontalWeights;
        var vSpan = kernel.VerticalWeights;
        for (int i = 0; i < hSize; i++) hKernel[i] = hSpan[i];
        for (int i = 0; i < vSize; i++) vKernel[i] = vSpan[i] * kernel.Factor;

        int tempRowBytes = width * 4;
        long totalBytes = (long)tempRowBytes * height;
        RentScratch(totalBytes, out var pooled, out var native);

        try
        {
            fixed (byte* pooledPtr = pooled)
            {
                byte* tempScan0 = pooled != null ? pooledPtr : native;
                bool isParallel = options.ProcessingMode is PixelProcessingMode.Parallel or PixelProcessingMode.ParallelVectorized;
                bool isVectorized = options.ProcessingMode is PixelProcessingMode.SequentialVectorized or PixelProcessingMode.ParallelVectorized;
                bool preserveAlpha = ShouldPreserveAlpha(kernel, options.AlphaMode);
                float bias = kernel.Bias;
                var borderMode = options.BorderMode;

                if (isParallel)
                {
                    Parallel.For(0, height, y =>
                        SeparableHorizontalRow(srcScan0 + y * srcRowBytes, tempScan0 + y * tempRowBytes, hKernel, rx, hSize, width, preserveAlpha, borderMode, isVectorized));
                    Parallel.For(0, height, y =>
                        SeparableVerticalRow(tempScan0, srcScan0 + y * srcRowBytes, dstScan0 + y * dstRowBytes, vKernel, ry, vSize, y, width, height, tempRowBytes, bias, preserveAlpha, borderMode, isVectorized, postProcessor));
                }
                else
                {
                    for (int y = 0; y < height; y++)
                    {
                        SeparableHorizontalRow(srcScan0 + y * srcRowBytes, tempScan0 + y * tempRowBytes, hKernel, rx, hSize, width, preserveAlpha, borderMode, isVectorized);
                    }
                    for (int y = 0; y < height; y++)
                    {
                        SeparableVerticalRow(tempScan0, srcScan0 + y * srcRowBytes, dstScan0 + y * dstRowBytes, vKernel, ry, vSize, y, width, height, tempRowBytes, bias, preserveAlpha, borderMode, isVectorized, postProcessor);
                    }
                }
            }
        }
        finally
        {
            ReturnScratch(pooled, native);
        }
    }

    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    private static void SeparableHorizontalRow(
        byte* srcRow,
        byte* dstRow,
        float* kernel,
        int radius,
        int size,
        int width,
        bool preserveAlpha,
        ConvolutionBorderMode borderMode,
        bool vectorized)
    {
        if (!vectorized)
        {
            for (int x = 0; x < width; x++)
            {
                float b = 0, g = 0, r = 0, a = preserveAlpha ? srcRow[x * 4 + 3] : 0;
                for (int k = -radius; k <= radius; k++)
                {
                    int sampleX = ResolveBorderCoord(x + k, width, borderMode);
                    if (sampleX < 0) continue;
                    byte* p = srcRow + sampleX * 4;
                    float w = kernel[k + radius];
                    b += p[0] * w; g += p[1] * w; r += p[2] * w;
                    if (!preserveAlpha) a += p[3] * w;
                }
                byte* outP = dstRow + x * 4;
                outP[0] = (byte)global::System.Math.Clamp((int)global::System.Math.Round(b), 0, 255);
                outP[1] = (byte)global::System.Math.Clamp((int)global::System.Math.Round(g), 0, 255);
                outP[2] = (byte)global::System.Math.Clamp((int)global::System.Math.Round(r), 0, 255);
                outP[3] = (byte)global::System.Math.Clamp((int)global::System.Math.Round(a), 0, 255);
            }
            return;
        }

        int interiorStart = global::System.Math.Min(radius, width);
        int interiorEnd = global::System.Math.Max(interiorStart, width - radius);

        for (int x = 0; x < interiorStart; x++)
        {
            float b = 0, g = 0, r = 0, a = preserveAlpha ? srcRow[x * 4 + 3] : 0;
            for (int k = -radius; k <= radius; k++)
            {
                int sampleX = ResolveBorderCoord(x + k, width, borderMode);
                if (sampleX < 0) continue;
                byte* p = srcRow + sampleX * 4;
                float w = kernel[k + radius];
                b += p[0] * w; g += p[1] * w; r += p[2] * w;
                if (!preserveAlpha) a += p[3] * w;
            }
            byte* outP = dstRow + x * 4;
            outP[0] = (byte)global::System.Math.Clamp((int)(b + 0.5f), 0, 255);
            outP[1] = (byte)global::System.Math.Clamp((int)(g + 0.5f), 0, 255);
            outP[2] = (byte)global::System.Math.Clamp((int)(r + 0.5f), 0, 255);
            outP[3] = (byte)global::System.Math.Clamp((int)(a + 0.5f), 0, 255);
        }

        int ix = interiorStart;
        if (Vector256.IsHardwareAccelerated)
        {
            for (; ix + 2 <= interiorEnd; ix += 2)
            {
                var acc = Vector256<float>.Zero;
                byte* srcWin = srcRow + (ix - radius) * 4;
                for (int i = 0; i < size; i++)
                {
                    acc += Load8BytesAsFloat256(srcWin + i * 4) * Vector256.Create(kernel[i]);
                }
                StoreFloat256As8Bytes(acc, dstRow + ix * 4);
                if (preserveAlpha)
                {
                    ulong origA = *(ulong*)(srcRow + ix * 4) & 0xFF000000FF000000UL;
                    *(ulong*)(dstRow + ix * 4) = (*(ulong*)(dstRow + ix * 4) & 0x00FFFFFF00FFFFFFUL) | origA;
                }
            }
        }

        if (Vector128.IsHardwareAccelerated)
        {
            for (; ix < interiorEnd; ix++)
            {
                var acc = Vector128<float>.Zero;
                byte* srcWin = srcRow + (ix - radius) * 4;
                for (int i = 0; i < size; i++)
                {
                    acc += Load4BytesAsFloat128(srcWin + i * 4) * Vector128.Create(kernel[i]);
                }
                StoreFloat128As4Bytes(acc, dstRow + ix * 4);
                if (preserveAlpha)
                {
                    dstRow[ix * 4 + 3] = srcRow[ix * 4 + 3];
                }
            }
        }

        for (; ix < interiorEnd; ix++)
        {
            float b = 0, g = 0, r = 0, a = preserveAlpha ? srcRow[ix * 4 + 3] : 0;
            byte* srcWin = srcRow + (ix - radius) * 4;
            for (int i = 0; i < size; i++)
            {
                byte* p = srcWin + i * 4;
                float w = kernel[i];
                b += p[0] * w; g += p[1] * w; r += p[2] * w;
                if (!preserveAlpha) a += p[3] * w;
            }
            byte* outP = dstRow + ix * 4;
            outP[0] = (byte)global::System.Math.Clamp((int)(b + 0.5f), 0, 255);
            outP[1] = (byte)global::System.Math.Clamp((int)(g + 0.5f), 0, 255);
            outP[2] = (byte)global::System.Math.Clamp((int)(r + 0.5f), 0, 255);
            outP[3] = (byte)global::System.Math.Clamp((int)(a + 0.5f), 0, 255);
        }

        for (int x = interiorEnd; x < width; x++)
        {
            float b = 0, g = 0, r = 0, a = preserveAlpha ? srcRow[x * 4 + 3] : 0;
            for (int k = -radius; k <= radius; k++)
            {
                int sampleX = ResolveBorderCoord(x + k, width, borderMode);
                if (sampleX < 0) continue;
                byte* p = srcRow + sampleX * 4;
                float w = kernel[k + radius];
                b += p[0] * w; g += p[1] * w; r += p[2] * w;
                if (!preserveAlpha) a += p[3] * w;
            }
            byte* outP = dstRow + x * 4;
            outP[0] = (byte)global::System.Math.Clamp((int)(b + 0.5f), 0, 255);
            outP[1] = (byte)global::System.Math.Clamp((int)(g + 0.5f), 0, 255);
            outP[2] = (byte)global::System.Math.Clamp((int)(r + 0.5f), 0, 255);
            outP[3] = (byte)global::System.Math.Clamp((int)(a + 0.5f), 0, 255);
        }
    }

    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    private static void SeparableVerticalRow<TPost>(
        byte* tempScan0,
        byte* origAlphaRow,
        byte* dstRow,
        float* kernel,
        int radius,
        int size,
        int y,
        int width,
        int height,
        int tempRowBytes,
        float bias,
        bool preserveAlpha,
        ConvolutionBorderMode borderMode,
        bool vectorized,
        TPost postProcessor)
        where TPost : struct, IConvolutionPostProcessor
    {
        byte** rowPtrs = stackalloc byte*[size];
        for (int i = 0; i < size; i++)
        {
            int sampleY = ResolveBorderCoord(y + i - radius, height, borderMode);
            rowPtrs[i] = sampleY < 0 ? null : tempScan0 + sampleY * tempRowBytes;
        }

        bool hasPost = typeof(TPost) != typeof(IdentityConvolutionPostProcessor);
        if (!vectorized || hasPost)
        {
            for (int x = 0; x < width; x++)
            {
                int offset = x * 4;
                float b = bias, g = bias, r = bias, a = preserveAlpha ? origAlphaRow[offset + 3] : bias;
                for (int i = 0; i < size; i++)
                {
                    if (rowPtrs[i] == null) continue;
                    byte* p = rowPtrs[i] + offset;
                    float w = kernel[i];
                    b += p[0] * w; g += p[1] * w; r += p[2] * w;
                    if (!preserveAlpha) a += p[3] * w;
                }

                if (hasPost)
                {
                    postProcessor.PostProcess(x, y, ref b, ref g, ref r, ref a);
                }

                byte* outP = dstRow + offset;
                outP[0] = (byte)global::System.Math.Clamp((int)global::System.Math.Round(b), 0, 255);
                outP[1] = (byte)global::System.Math.Clamp((int)global::System.Math.Round(g), 0, 255);
                outP[2] = (byte)global::System.Math.Clamp((int)global::System.Math.Round(r), 0, 255);
                outP[3] = (byte)global::System.Math.Clamp((int)global::System.Math.Round(a), 0, 255);
            }
            return;
        }

        int x2 = 0;
        if (Vector256.IsHardwareAccelerated)
        {
            var vBias = Vector256.Create(bias);
            for (; x2 + 4 <= width; x2 += 4)
            {
                var accLo = vBias;
                var accHi = vBias;
                int byteOffset = x2 * 4;
                for (int i = 0; i < size; i++)
                {
                    if (rowPtrs[i] == null) continue;
                    byte* p = rowPtrs[i] + byteOffset;
                    var vW = Vector256.Create(kernel[i]);
                    accLo += Load8BytesAsFloat256(p) * vW;
                    accHi += Load8BytesAsFloat256(p + 8) * vW;
                }
                StoreFloat256As8Bytes(accLo, dstRow + byteOffset);
                StoreFloat256As8Bytes(accHi, dstRow + byteOffset + 8);
                if (preserveAlpha)
                {
                    *(ulong*)(dstRow + byteOffset) = (*(ulong*)(dstRow + byteOffset) & 0x00FFFFFF00FFFFFFUL) | (*(ulong*)(origAlphaRow + byteOffset) & 0xFF000000FF000000UL);
                    *(ulong*)(dstRow + byteOffset + 8) = (*(ulong*)(dstRow + byteOffset + 8) & 0x00FFFFFF00FFFFFFUL) | (*(ulong*)(origAlphaRow + byteOffset + 8) & 0xFF000000FF000000UL);
                }
            }

            if (x2 + 2 <= width)
            {
                var acc = vBias;
                int byteOffset = x2 * 4;
                for (int i = 0; i < size; i++)
                {
                    if (rowPtrs[i] == null) continue;
                    acc += Load8BytesAsFloat256(rowPtrs[i] + byteOffset) * Vector256.Create(kernel[i]);
                }
                StoreFloat256As8Bytes(acc, dstRow + byteOffset);
                if (preserveAlpha)
                {
                    *(ulong*)(dstRow + byteOffset) = (*(ulong*)(dstRow + byteOffset) & 0x00FFFFFF00FFFFFFUL) | (*(ulong*)(origAlphaRow + byteOffset) & 0xFF000000FF000000UL);
                }
                x2 += 2;
            }
        }

        if (Vector128.IsHardwareAccelerated)
        {
            var vBias = Vector128.Create(bias);
            for (; x2 < width; x2++)
            {
                var acc = vBias;
                int byteOffset = x2 * 4;
                for (int i = 0; i < size; i++)
                {
                    if (rowPtrs[i] == null) continue;
                    acc += Load4BytesAsFloat128(rowPtrs[i] + byteOffset) * Vector128.Create(kernel[i]);
                }
                StoreFloat128As4Bytes(acc, dstRow + byteOffset);
                if (preserveAlpha)
                {
                    dstRow[byteOffset + 3] = origAlphaRow[byteOffset + 3];
                }
            }
            return;
        }

        for (; x2 < width; x2++)
        {
            int offset = x2 * 4;
            float b = bias, g = bias, r = bias, a = preserveAlpha ? origAlphaRow[offset + 3] : bias;
            for (int i = 0; i < size; i++)
            {
                if (rowPtrs[i] == null) continue;
                byte* p = rowPtrs[i] + offset;
                float w = kernel[i];
                b += p[0] * w; g += p[1] * w; r += p[2] * w;
                if (!preserveAlpha) a += p[3] * w;
            }
            byte* outP = dstRow + offset;
            outP[0] = (byte)global::System.Math.Clamp((int)(b + 0.5f), 0, 255);
            outP[1] = (byte)global::System.Math.Clamp((int)(g + 0.5f), 0, 255);
            outP[2] = (byte)global::System.Math.Clamp((int)(r + 0.5f), 0, 255);
            outP[3] = (byte)global::System.Math.Clamp((int)(a + 0.5f), 0, 255);
        }
    }

    // ==========================================
    // 管線 C：雙核方向梯度算子 (GradientDual2D)
    // ==========================================

    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    private static void ExecuteGradientDual2D<TPost>(
        WriteableBitmap src,
        WriteableBitmap dst,
        ConvolutionKernel kernel,
        TPost postProcessor,
        ConvolutionOptions options)
        where TPost : struct, IConvolutionPostProcessor
    {
        if (options.GradientChannelMode == GradientChannelMode.PerChannelRgb)
        {
            ExecuteGradientPerChannelRgb(src, dst, kernel, postProcessor, options);
            return;
        }

        bool inPlace = ReferenceEquals(src, dst);
        using var srcFb = src.Lock();
        using var dstFb = inPlace ? null : dst.Lock();

        int width = srcFb.Size.Width;
        int height = srcFb.Size.Height;
        int srcRowBytes = srcFb.RowBytes;
        int dstRowBytes = dstFb?.RowBytes ?? srcRowBytes;

        byte* srcScan0 = (byte*)srcFb.Address;
        byte* dstScan0 = dstFb != null ? (byte*)dstFb.Address : srcScan0;

        bool isParallel = options.ProcessingMode is PixelProcessingMode.Parallel or PixelProcessingMode.ParallelVectorized;
        bool isVectorized = options.ProcessingMode is PixelProcessingMode.SequentialVectorized or PixelProcessingMode.ParallelVectorized;
        bool preserveAlpha = options.AlphaMode == ConvolutionAlphaMode.Preserve;
        bool useL2 = options.GradientNormMode == GradientNormMode.L2;
        float threshold = options.GradientThreshold;
        float bias = kernel.Bias;
        int rx = kernel.RadiusX;
        int ry = kernel.RadiusY;
        var tapsX = kernel.SparseGxTaps;
        var tapsY = kernel.SparseGyTaps;
        var borderMode = options.BorderMode;

        // 保留原始 Alpha 時若為原地操作，需先記錄 Alpha 或複製，但單通道亮度緩衝僅 1B/px；若為原地保留 Alpha 可在 Pass 2 讀 srcScan0（尚未被寫入的同座標）!
        long lumBytes = (long)width * height;
        RentScratch(lumBytes, out var pooledLum, out var nativeLum);

        try
        {
            fixed (byte* pooledPtr = pooledLum)
            {
                byte* lumScan0 = pooledLum != null ? pooledPtr : nativeLum;

                if (isParallel)
                {
                    Parallel.For(0, height, y =>
                        ExtractLuminanceRow(srcScan0 + y * srcRowBytes, lumScan0 + y * width, width, isVectorized));
                    Parallel.For(0, height, y =>
                        ComputeLuminanceGradientRow(
                            lumScan0, srcScan0 + y * srcRowBytes, dstScan0 + y * dstRowBytes,
                            y, width, height, rx, ry, tapsX, tapsY, bias, threshold, useL2, preserveAlpha, borderMode, isVectorized, postProcessor));
                }
                else
                {
                    for (int y = 0; y < height; y++)
                    {
                        ExtractLuminanceRow(srcScan0 + y * srcRowBytes, lumScan0 + y * width, width, isVectorized);
                    }
                    for (int y = 0; y < height; y++)
                    {
                        ComputeLuminanceGradientRow(
                            lumScan0, srcScan0 + y * srcRowBytes, dstScan0 + y * dstRowBytes,
                            y, width, height, rx, ry, tapsX, tapsY, bias, threshold, useL2, preserveAlpha, borderMode, isVectorized, postProcessor);
                    }
                }
            }
        }
        finally
        {
            ReturnScratch(pooledLum, nativeLum);
        }
    }

    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    private static void ExtractLuminanceRow(byte* srcRow, byte* lumRow, int width, bool vectorized)
    {
        uint* px = (uint*)srcRow;
        int x = 0;

        if (vectorized && Vector256.IsHardwareAccelerated && width >= 8)
        {
            var vMaskByte = Vector256.Create(0xFFu);
            var vWR = Vector256.Create(9798u);
            var vWG = Vector256.Create(19235u);
            var vWB = Vector256.Create(3735u);
            var vBias = Vector256.Create(16384u);

            int limit = width - (width % 8);
            for (; x < limit; x += 8)
            {
                var v = Vector256.Load(px + x);
                var b = v & vMaskByte;
                var g = (v >>> 8) & vMaskByte;
                var r = (v >>> 16) & vMaskByte;
                var gray = (r * vWR + g * vWG + b * vWB + vBias) >>> 15;

                var u16 = Vector128.Narrow(gray.GetLower(), gray.GetUpper());
                var u8 = Vector128.Narrow(u16, u16);
                *(ulong*)(lumRow + x) = u8.AsUInt64().GetElement(0);
            }
        }

        if (vectorized && Vector128.IsHardwareAccelerated && width - x >= 4)
        {
            var vMaskByte = Vector128.Create(0xFFu);
            var vWR = Vector128.Create(9798u);
            var vWG = Vector128.Create(19235u);
            var vWB = Vector128.Create(3735u);
            var vBias = Vector128.Create(16384u);

            int limit = x + ((width - x) & ~3);
            for (; x < limit; x += 4)
            {
                var v = Vector128.Load(px + x);
                var b = v & vMaskByte;
                var g = (v >>> 8) & vMaskByte;
                var r = (v >>> 16) & vMaskByte;
                var gray = (r * vWR + g * vWG + b * vWB + vBias) >>> 15;

                var u16 = Vector128.Narrow(gray, gray);
                var u8 = Vector128.Narrow(u16, u16);
                *(uint*)(lumRow + x) = u8.AsUInt32().GetElement(0);
            }
        }

        for (; x < width; x++)
        {
            uint v = px[x];
            lumRow[x] = (byte)((((v >> 16) & 0xFFu) * 9798u + ((v >> 8) & 0xFFu) * 19235u + (v & 0xFFu) * 3735u + 16384u) >> 15);
        }
    }

    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    private static void ComputeLuminanceGradientRow<TPost>(
        byte* lumScan0,
        byte* origSrcRow,
        byte* dstRow,
        int y,
        int width,
        int height,
        int rx,
        int ry,
        ConvolutionKernel.SparseTap[] tapsX,
        ConvolutionKernel.SparseTap[] tapsY,
        float bias,
        float threshold,
        bool useL2,
        bool preserveAlpha,
        ConvolutionBorderMode borderMode,
        bool vectorized,
        TPost postProcessor)
        where TPost : struct, IConvolutionPostProcessor
    {
        bool hasPost = typeof(TPost) != typeof(IdentityConvolutionPostProcessor);
        bool rowInterior = y >= ry && y < height - ry;

        if (!rowInterior || !vectorized || hasPost)
        {
            if (vectorized && rowInterior && !hasPost)
            {
                int iStart = global::System.Math.Min(rx, width);
                int iEnd = global::System.Math.Max(iStart, width - rx);
                LuminanceGradientBorderRange(lumScan0, origSrcRow, dstRow, y, 0, iStart, width, height, tapsX, tapsY, bias, threshold, useL2, preserveAlpha, borderMode, postProcessor);
                LuminanceGradientInteriorSimd(lumScan0, origSrcRow, dstRow, y, iStart, iEnd, width, tapsX, tapsY, bias, threshold, useL2, preserveAlpha);
                LuminanceGradientBorderRange(lumScan0, origSrcRow, dstRow, y, iEnd, width, width, height, tapsX, tapsY, bias, threshold, useL2, preserveAlpha, borderMode, postProcessor);
                return;
            }

            LuminanceGradientBorderRange(lumScan0, origSrcRow, dstRow, y, 0, width, width, height, tapsX, tapsY, bias, threshold, useL2, preserveAlpha, borderMode, postProcessor);
            return;
        }

        int interiorStart = global::System.Math.Min(rx, width);
        int interiorEnd = global::System.Math.Max(interiorStart, width - rx);

        LuminanceGradientBorderRange(lumScan0, origSrcRow, dstRow, y, 0, interiorStart, width, height, tapsX, tapsY, bias, threshold, useL2, preserveAlpha, borderMode, postProcessor);
        LuminanceGradientInteriorSimd(lumScan0, origSrcRow, dstRow, y, interiorStart, interiorEnd, width, tapsX, tapsY, bias, threshold, useL2, preserveAlpha);
        LuminanceGradientBorderRange(lumScan0, origSrcRow, dstRow, y, interiorEnd, width, width, height, tapsX, tapsY, bias, threshold, useL2, preserveAlpha, borderMode, postProcessor);
    }

    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    private static void LuminanceGradientInteriorSimd(
        byte* lumScan0,
        byte* origSrcRow,
        byte* dstRow,
        int y,
        int xStart,
        int xEnd,
        int width,
        ConvolutionKernel.SparseTap[] tapsX,
        ConvolutionKernel.SparseTap[] tapsY,
        float bias,
        float threshold,
        bool useL2,
        bool preserveAlpha)
    {
        uint* dstPx = (uint*)dstRow;
        uint* srcPx = (uint*)origSrcRow;
        int x = xStart;

        if (Vector256.IsHardwareAccelerated && xEnd - x >= 8)
        {
            var vBias = Vector256.Create(bias);
            var vMax = Vector256.Create(255.0f);
            var vThresh = Vector256.Create(threshold);
            var vZero = Vector256<float>.Zero;
            var vOpaqueAlpha = Vector256.Create(0xFF000000u);
            var vMaskAlpha = Vector256.Create(0xFF000000u);
            var vRep = Vector256.Create(0x00010101u);

            for (; x + 8 <= xEnd; x += 8)
            {
                var gx = Vector256<float>.Zero;
                for (int t = 0; t < tapsX.Length; t++)
                {
                    var tap = tapsX[t];
                    gx += Load8BytesAsFloat256(lumScan0 + (y + tap.Dy) * width + (x + tap.Dx)) * Vector256.Create(tap.Weight);
                }

                var gy = Vector256<float>.Zero;
                for (int t = 0; t < tapsY.Length; t++)
                {
                    var tap = tapsY[t];
                    gy += Load8BytesAsFloat256(lumScan0 + (y + tap.Dy) * width + (x + tap.Dx)) * Vector256.Create(tap.Weight);
                }

                var mag = useL2
                    ? Vector256.Sqrt(gx * gx + gy * gy)
                    : Vector256.Abs(gx) + Vector256.Abs(gy);

                mag = Vector256.Min(Vector256.Max(mag + vBias, vZero), vMax);
                if (threshold > 0.0f)
                {
                    mag = Vector256.ConditionalSelect(Vector256.GreaterThanOrEqual(mag, vThresh), mag, vZero);
                }

                var magInt = Vector256.ConvertToInt32(Vector256.Floor(mag));
                var alphaVec = preserveAlpha ? (Vector256.Load(srcPx + x) & vMaskAlpha) : vOpaqueAlpha;
                Vector256.Store(alphaVec | (magInt.AsUInt32() * vRep), dstPx + x);
            }
        }

        if (Vector128.IsHardwareAccelerated && xEnd - x >= 4)
        {
            var vBias = Vector128.Create(bias);
            var vMax = Vector128.Create(255.0f);
            var vThresh = Vector128.Create(threshold);
            var vZero = Vector128<float>.Zero;
            var vOpaqueAlpha = Vector128.Create(0xFF000000u);
            var vMaskAlpha = Vector128.Create(0xFF000000u);
            var vRep = Vector128.Create(0x00010101u);

            for (; x + 4 <= xEnd; x += 4)
            {
                var gx = Vector128<float>.Zero;
                for (int t = 0; t < tapsX.Length; t++)
                {
                    var tap = tapsX[t];
                    gx += Load4BytesAsFloat128(lumScan0 + (y + tap.Dy) * width + (x + tap.Dx)) * Vector128.Create(tap.Weight);
                }

                var gy = Vector128<float>.Zero;
                for (int t = 0; t < tapsY.Length; t++)
                {
                    var tap = tapsY[t];
                    gy += Load4BytesAsFloat128(lumScan0 + (y + tap.Dy) * width + (x + tap.Dx)) * Vector128.Create(tap.Weight);
                }

                var mag = useL2
                    ? Vector128.Sqrt(gx * gx + gy * gy)
                    : Vector128.Abs(gx) + Vector128.Abs(gy);

                mag = Vector128.Min(Vector128.Max(mag + vBias, vZero), vMax);
                if (threshold > 0.0f)
                {
                    mag = Vector128.ConditionalSelect(Vector128.GreaterThanOrEqual(mag, vThresh), mag, vZero);
                }

                var magInt = Vector128.ConvertToInt32(Vector128.Floor(mag));
                var alphaVec = preserveAlpha ? (Vector128.Load(srcPx + x) & vMaskAlpha) : vOpaqueAlpha;
                Vector128.Store(alphaVec | (magInt.AsUInt32() * vRep), dstPx + x);
            }
        }

        for (; x < xEnd; x++)
        {
            float gx = 0f, gy = 0f;
            for (int t = 0; t < tapsX.Length; t++)
            {
                var tap = tapsX[t];
                gx += lumScan0[(y + tap.Dy) * width + (x + tap.Dx)] * tap.Weight;
            }
            for (int t = 0; t < tapsY.Length; t++)
            {
                var tap = tapsY[t];
                gy += lumScan0[(y + tap.Dy) * width + (x + tap.Dx)] * tap.Weight;
            }

            float mag = (useL2 ? MathF.Sqrt(gx * gx + gy * gy) : MathF.Abs(gx) + MathF.Abs(gy)) + bias;
            mag = global::System.Math.Clamp(mag, 0f, 255f);
            if (mag < threshold) mag = 0f;

            uint val = (uint)(int)mag;
            uint alpha = preserveAlpha ? (srcPx[x] & 0xFF000000u) : 0xFF000000u;
            dstPx[x] = alpha | (val * 0x00010101u);
        }
    }

    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    private static void LuminanceGradientBorderRange<TPost>(
        byte* lumScan0,
        byte* origSrcRow,
        byte* dstRow,
        int y,
        int xStart,
        int xEnd,
        int width,
        int height,
        ConvolutionKernel.SparseTap[] tapsX,
        ConvolutionKernel.SparseTap[] tapsY,
        float bias,
        float threshold,
        bool useL2,
        bool preserveAlpha,
        ConvolutionBorderMode borderMode,
        TPost postProcessor)
        where TPost : struct, IConvolutionPostProcessor
    {
        uint* dstPx = (uint*)dstRow;
        uint* srcPx = (uint*)origSrcRow;
        bool hasPost = typeof(TPost) != typeof(IdentityConvolutionPostProcessor);

        for (int x = xStart; x < xEnd; x++)
        {
            float gx = 0f, gy = 0f;
            for (int t = 0; t < tapsX.Length; t++)
            {
                var tap = tapsX[t];
                int sy = ResolveBorderCoord(y + tap.Dy, height, borderMode);
                if (sy < 0) continue;
                int sx = ResolveBorderCoord(x + tap.Dx, width, borderMode);
                if (sx < 0) continue;
                gx += lumScan0[sy * width + sx] * tap.Weight;
            }
            for (int t = 0; t < tapsY.Length; t++)
            {
                var tap = tapsY[t];
                int sy = ResolveBorderCoord(y + tap.Dy, height, borderMode);
                if (sy < 0) continue;
                int sx = ResolveBorderCoord(x + tap.Dx, width, borderMode);
                if (sx < 0) continue;
                gy += lumScan0[sy * width + sx] * tap.Weight;
            }

            float mag = (useL2 ? MathF.Sqrt(gx * gx + gy * gy) : MathF.Abs(gx) + MathF.Abs(gy)) + bias;
            if (threshold > 0.0f && mag < threshold) mag = 0f;

            if (hasPost)
            {
                float b = mag, g = mag, r = mag;
                float a = preserveAlpha ? origSrcRow[x * 4 + 3] : 255f;
                postProcessor.PostProcess(x, y, ref b, ref g, ref r, ref a);
                byte* outP = dstRow + x * 4;
                outP[0] = (byte)global::System.Math.Clamp((int)global::System.Math.Round(b), 0, 255);
                outP[1] = (byte)global::System.Math.Clamp((int)global::System.Math.Round(g), 0, 255);
                outP[2] = (byte)global::System.Math.Clamp((int)global::System.Math.Round(r), 0, 255);
                outP[3] = (byte)global::System.Math.Clamp((int)global::System.Math.Round(a), 0, 255);
            }
            else
            {
                uint val = (uint)global::System.Math.Clamp((int)mag, 0, 255);
                uint alpha = preserveAlpha ? (srcPx[x] & 0xFF000000u) : 0xFF000000u;
                dstPx[x] = alpha | (val * 0x00010101u);
            }
        }
    }

    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    private static void ExecuteGradientPerChannelRgb<TPost>(
        WriteableBitmap src,
        WriteableBitmap dst,
        ConvolutionKernel kernel,
        TPost postProcessor,
        ConvolutionOptions options)
        where TPost : struct, IConvolutionPostProcessor
    {
        bool inPlace = ReferenceEquals(src, dst);
        using var srcFb = src.Lock();
        using var dstFb = inPlace ? null : dst.Lock();

        int width = srcFb.Size.Width;
        int height = srcFb.Size.Height;
        int srcRowBytes = srcFb.RowBytes;
        int dstRowBytes = dstFb?.RowBytes ?? srcRowBytes;

        byte* srcOriginal = (byte*)srcFb.Address;
        byte* dstScan0 = dstFb != null ? (byte*)dstFb.Address : srcOriginal;

        long copyBytes = inPlace ? (long)srcRowBytes * height : 0;
        byte[]? pooled = null;
        byte* native = null;
        if (inPlace)
        {
            RentScratch(copyBytes, out pooled, out native);
        }

        try
        {
            fixed (byte* pooledPtr = pooled)
            {
                byte* srcScan0 = inPlace ? (pooled != null ? pooledPtr : native) : srcOriginal;
                if (inPlace)
                {
                    Buffer.MemoryCopy(srcOriginal, srcScan0, copyBytes, copyBytes);
                }

                bool isParallel = options.ProcessingMode is PixelProcessingMode.Parallel or PixelProcessingMode.ParallelVectorized;
                bool isVectorized = options.ProcessingMode is PixelProcessingMode.SequentialVectorized or PixelProcessingMode.ParallelVectorized;
                bool preserveAlpha = options.AlphaMode == ConvolutionAlphaMode.Preserve;
                bool useL2 = options.GradientNormMode == GradientNormMode.L2;
                float threshold = options.GradientThreshold;
                float bias = kernel.Bias;
                int rx = kernel.RadiusX;
                int ry = kernel.RadiusY;
                var tapsX = kernel.SparseGxTaps;
                var tapsY = kernel.SparseGyTaps;
                var borderMode = options.BorderMode;

                if (isParallel)
                {
                    Parallel.For(0, height, y =>
                        PerChannelRgbGradientRow(srcScan0, dstScan0 + y * dstRowBytes, y, width, height, srcRowBytes, rx, ry, tapsX, tapsY, bias, threshold, useL2, preserveAlpha, borderMode, isVectorized, postProcessor));
                }
                else
                {
                    for (int y = 0; y < height; y++)
                    {
                        PerChannelRgbGradientRow(srcScan0, dstScan0 + y * dstRowBytes, y, width, height, srcRowBytes, rx, ry, tapsX, tapsY, bias, threshold, useL2, preserveAlpha, borderMode, isVectorized, postProcessor);
                    }
                }
            }
        }
        finally
        {
            ReturnScratch(pooled, native);
        }
    }

    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    private static void PerChannelRgbGradientRow<TPost>(
        byte* srcScan0,
        byte* dstRow,
        int y,
        int width,
        int height,
        int srcRowBytes,
        int rx,
        int ry,
        ConvolutionKernel.SparseTap[] tapsX,
        ConvolutionKernel.SparseTap[] tapsY,
        float bias,
        float threshold,
        bool useL2,
        bool preserveAlpha,
        ConvolutionBorderMode borderMode,
        bool vectorized,
        TPost postProcessor)
        where TPost : struct, IConvolutionPostProcessor
    {
        byte* srcCurrRow = srcScan0 + y * srcRowBytes;
        bool hasPost = typeof(TPost) != typeof(IdentityConvolutionPostProcessor);
        bool rowInterior = y >= ry && y < height - ry;

        if (!rowInterior || !vectorized || hasPost)
        {
            PerChannelRgbGradientBorderRange(srcScan0, srcCurrRow, dstRow, y, 0, width, width, height, srcRowBytes, tapsX, tapsY, bias, threshold, useL2, preserveAlpha, borderMode, postProcessor);
            return;
        }

        int interiorStart = global::System.Math.Min(rx, width);
        int interiorEnd = global::System.Math.Max(interiorStart, width - rx);

        PerChannelRgbGradientBorderRange(srcScan0, srcCurrRow, dstRow, y, 0, interiorStart, width, height, srcRowBytes, tapsX, tapsY, bias, threshold, useL2, preserveAlpha, borderMode, postProcessor);

        int x = interiorStart;
        if (Vector256.IsHardwareAccelerated && interiorEnd - x >= 2)
        {
            var vBias = Vector256.Create(bias);
            var vMax = Vector256.Create(255.0f);
            var vZero = Vector256<float>.Zero;
            var vThresh = Vector256.Create(threshold);

            for (; x + 2 <= interiorEnd; x += 2)
            {
                var gx = Vector256<float>.Zero;
                for (int t = 0; t < tapsX.Length; t++)
                {
                    var tap = tapsX[t];
                    gx += Load8BytesAsFloat256(srcScan0 + (y + tap.Dy) * srcRowBytes + (x + tap.Dx) * 4) * Vector256.Create(tap.Weight);
                }
                var gy = Vector256<float>.Zero;
                for (int t = 0; t < tapsY.Length; t++)
                {
                    var tap = tapsY[t];
                    gy += Load8BytesAsFloat256(srcScan0 + (y + tap.Dy) * srcRowBytes + (x + tap.Dx) * 4) * Vector256.Create(tap.Weight);
                }

                var mag = useL2 ? Vector256.Sqrt(gx * gx + gy * gy) : Vector256.Abs(gx) + Vector256.Abs(gy);
                mag = Vector256.Min(Vector256.Max(mag + vBias, vZero), vMax);
                if (threshold > 0.0f)
                {
                    mag = Vector256.ConditionalSelect(Vector256.GreaterThanOrEqual(mag, vThresh), mag, vZero);
                }

                byte* outPtr = dstRow + x * 4;
                StoreFloat256As8Bytes(mag, outPtr);
                ulong alphaMask = preserveAlpha ? (*(ulong*)(srcCurrRow + x * 4) & 0xFF000000FF000000UL) : 0xFF000000FF000000UL;
                *(ulong*)outPtr = (*(ulong*)outPtr & 0x00FFFFFF00FFFFFFUL) | alphaMask;
            }
        }

        if (Vector128.IsHardwareAccelerated)
        {
            var vBias = Vector128.Create(bias);
            var vMax = Vector128.Create(255.0f);
            var vZero = Vector128<float>.Zero;
            var vThresh = Vector128.Create(threshold);

            for (; x < interiorEnd; x++)
            {
                var gx = Vector128<float>.Zero;
                for (int t = 0; t < tapsX.Length; t++)
                {
                    var tap = tapsX[t];
                    gx += Load4BytesAsFloat128(srcScan0 + (y + tap.Dy) * srcRowBytes + (x + tap.Dx) * 4) * Vector128.Create(tap.Weight);
                }
                var gy = Vector128<float>.Zero;
                for (int t = 0; t < tapsY.Length; t++)
                {
                    var tap = tapsY[t];
                    gy += Load4BytesAsFloat128(srcScan0 + (y + tap.Dy) * srcRowBytes + (x + tap.Dx) * 4) * Vector128.Create(tap.Weight);
                }

                var mag = useL2 ? Vector128.Sqrt(gx * gx + gy * gy) : Vector128.Abs(gx) + Vector128.Abs(gy);
                mag = Vector128.Min(Vector128.Max(mag + vBias, vZero), vMax);
                if (threshold > 0.0f)
                {
                    mag = Vector128.ConditionalSelect(Vector128.GreaterThanOrEqual(mag, vThresh), mag, vZero);
                }

                byte* outPtr = dstRow + x * 4;
                StoreFloat128As4Bytes(mag, outPtr);
                outPtr[3] = preserveAlpha ? srcCurrRow[x * 4 + 3] : (byte)255;
            }
        }
        else
        {
            PerChannelRgbGradientBorderRange(srcScan0, srcCurrRow, dstRow, y, x, interiorEnd, width, height, srcRowBytes, tapsX, tapsY, bias, threshold, useL2, preserveAlpha, borderMode, postProcessor);
        }

        PerChannelRgbGradientBorderRange(srcScan0, srcCurrRow, dstRow, y, interiorEnd, width, width, height, srcRowBytes, tapsX, tapsY, bias, threshold, useL2, preserveAlpha, borderMode, postProcessor);
    }

    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    private static void PerChannelRgbGradientBorderRange<TPost>(
        byte* srcScan0,
        byte* srcCurrRow,
        byte* dstRow,
        int y,
        int xStart,
        int xEnd,
        int width,
        int height,
        int srcRowBytes,
        ConvolutionKernel.SparseTap[] tapsX,
        ConvolutionKernel.SparseTap[] tapsY,
        float bias,
        float threshold,
        bool useL2,
        bool preserveAlpha,
        ConvolutionBorderMode borderMode,
        TPost postProcessor)
        where TPost : struct, IConvolutionPostProcessor
    {
        bool hasPost = typeof(TPost) != typeof(IdentityConvolutionPostProcessor);

        for (int x = xStart; x < xEnd; x++)
        {
            float gxb = 0, gxg = 0, gxr = 0;
            float gyb = 0, gyg = 0, gyr = 0;

            for (int t = 0; t < tapsX.Length; t++)
            {
                var tap = tapsX[t];
                int sy = ResolveBorderCoord(y + tap.Dy, height, borderMode);
                if (sy < 0) continue;
                int sx = ResolveBorderCoord(x + tap.Dx, width, borderMode);
                if (sx < 0) continue;
                byte* p = srcScan0 + sy * srcRowBytes + sx * 4;
                float w = tap.Weight;
                gxb += p[0] * w; gxg += p[1] * w; gxr += p[2] * w;
            }
            for (int t = 0; t < tapsY.Length; t++)
            {
                var tap = tapsY[t];
                int sy = ResolveBorderCoord(y + tap.Dy, height, borderMode);
                if (sy < 0) continue;
                int sx = ResolveBorderCoord(x + tap.Dx, width, borderMode);
                if (sx < 0) continue;
                byte* p = srcScan0 + sy * srcRowBytes + sx * 4;
                float w = tap.Weight;
                gyb += p[0] * w; gyg += p[1] * w; gyr += p[2] * w;
            }

            float mb = (useL2 ? MathF.Sqrt(gxb * gxb + gyb * gyb) : MathF.Abs(gxb) + MathF.Abs(gyb)) + bias;
            float mg = (useL2 ? MathF.Sqrt(gxg * gxg + gyg * gyg) : MathF.Abs(gxg) + MathF.Abs(gyg)) + bias;
            float mr = (useL2 ? MathF.Sqrt(gxr * gxr + gyr * gyr) : MathF.Abs(gxr) + MathF.Abs(gyr)) + bias;
            float ma = preserveAlpha ? srcCurrRow[x * 4 + 3] : 255f;

            if (threshold > 0.0f)
            {
                if (mb < threshold) mb = 0f;
                if (mg < threshold) mg = 0f;
                if (mr < threshold) mr = 0f;
            }

            if (hasPost)
            {
                postProcessor.PostProcess(x, y, ref mb, ref mg, ref mr, ref ma);
            }

            byte* outP = dstRow + x * 4;
            outP[0] = (byte)global::System.Math.Clamp((int)global::System.Math.Round(mb), 0, 255);
            outP[1] = (byte)global::System.Math.Clamp((int)global::System.Math.Round(mg), 0, 255);
            outP[2] = (byte)global::System.Math.Clamp((int)global::System.Math.Round(mr), 0, 255);
            outP[3] = (byte)global::System.Math.Clamp((int)global::System.Math.Round(ma), 0, 255);
        }
    }
}

/// <summary>
/// WriteableBitmap 與 Bitmap 的流暢卷積擴充方法入口。
/// </summary>
public static class ConvolutionExtensions
{
    public static WriteableBitmap ApplyConvolution(
        this WriteableBitmap bitmap,
        ConvolutionKernel kernel,
        ConvolutionOptions? options = null)
    {
        ImageConvolution.Apply(bitmap, kernel, options);
        return bitmap;
    }

    public static WriteableBitmap ApplyConvolution<TPost>(
        this WriteableBitmap bitmap,
        ConvolutionKernel kernel,
        TPost postProcessor,
        ConvolutionOptions? options = null)
        where TPost : struct, IConvolutionPostProcessor
    {
        ImageConvolution.Apply(bitmap, kernel, postProcessor, options);
        return bitmap;
    }

    public static WriteableBitmap Convolve(
        this Bitmap bitmap,
        ConvolutionKernel kernel,
        ConvolutionOptions? options = null) =>
        ImageConvolution.Convolve(bitmap, kernel, options);

    public static WriteableBitmap Convolve<TPost>(
        this Bitmap bitmap,
        ConvolutionKernel kernel,
        TPost postProcessor,
        ConvolutionOptions? options = null)
        where TPost : struct, IConvolutionPostProcessor =>
        ImageConvolution.Convolve(bitmap, kernel, postProcessor, options);
}
